import json
from datetime import datetime, timezone
from pathlib import Path
OUT=Path('/workspace/output/evidence')
packet=json.loads((OUT/'claims.json').read_text())
checks=json.loads((OUT/'verifier-checks.json').read_text())
back_counter='OFFLINE SYNTHETIC fixture: Back pointer activation returns to introduction and focuses its heading, but Back is either absent from sequential keyboard traversal or ignores Enter. Executing all six written steps passes every assertion; executing contract Back traversal=Tab, activation=Enter leaves state first-question instead of expected introduction. Actual traces/failures: verifier-checks.json batch_2_ui.back-not-tabbable and batch_2_ui.back-enter-broken. This demonstrates a protocol false negative, not a live website defect.'
help_counter='OFFLINE SYNTHETIC fixtures: summary responds to click but ignores Space or Enter. All six protocol steps pass using its unspecified summary activation as click. Contract Enter/Space/Enter execution records actual help-open values differing from required true/false/true. In summary-space-broken, Space leaves help open (actual true, expected false); in summary-enter-broken, initial Enter leaves help closed (actual false, expected true). Actual traces: verifier-checks.json batch_2_ui.summary-space-broken and batch_2_ui.summary-enter-broken. No live website behavior is inferred.'
method_counter='OFFLINE SYNTHETIC request queue: GET https://qaizen.io/labs followed by POST https://qaizen.io/synthetic-analytics. With no extra policy harness, both reach an in-memory sink and the UI assertions remain unaffected; with the contract method policy applied, the POST is blocked with reason method and its event is retained. Expected: read-only-policy evidence, including blocked-POST effects. Actual target supplies neither enforcement nor verification/retention instructions, so its six assertions cannot distinguish these executions. See verifier-checks.json batch_1_network; no network request was attempted or sent.'
origin_counter='OFFLINE SYNTHETIC request queue includes GET https://outside.invalid/synthetic-asset after authorized entry. With no extra policy harness it reaches an in-memory sink; with the supplied origin policy it is blocked with reason origin. UI assertions do not inspect this event. Expected: observation established within https://qaizen.io; actual written six-step procedure has no origin-policy observation or enforcement step to distinguish the executions. See verifier-checks.json batch_1_network. No actual origin crossing or website request is alleged.'
back_ref='Attempted refutation: line 10 asserts introduction heading focus, and line 8 already uses Tab/Enter for Close. The healthy synthetic fixture passes both procedures, but the two defective Back fixtures still pass every target assertion. Focus after a pointer action does not establish how Back was reached or activated; the earlier keyboard action is for a different control. Contract line 15 and checker lines 35-36 explicitly require Back traversal/Enter.'
help_ref='Attempted refutation: opening using summary at line 7 could be interpreted as Enter, and line 8 proves keyboard Close. Even granting Enter opening, there is no summary Space close or Enter reopen step. The summary-space-broken fixture passes the written click-opening path while failing the required Space transition; a healthy fixture passes both. Close cannot substitute for the specifically declared summary transitions at contract lines 11-13.'
method_ref='Attempted refutation: the supplied contract/checker or an external observation harness might enforce read-only behavior. Running the actual validator returns valid=true and explicitly limits itself to contract consistency; source lines 9-43 consume JSON only and never inspect the target execution. The synthetic explicit-policy control blocks the POST correctly, showing an external harness could fix runtime safety, but the target never requests or verifies that setup or the retained blocked effects. This confirms only the procedure omission.'
origin_ref='Attempted refutation: authorized entry_url and observation-policy.json might suffice to constrain later observation. The validator computes only entry_url origin at lines 12-15; it has no input for followed links, redirects, or subrequests. The explicit-policy synthetic control correctly blocks outside.invalid, but nothing in target lines 5-10 loads, enforces, or observes this boundary. Knowing the first URL is allowed does not supply origin-policy evidence for the journey.'
items={
'C-1':(back_counter,back_ref,'When pointer Back works but sequential keyboard Back fails, the required keyboard-back check can be missed.'),
'C-2':(help_counter,help_ref,'When summary Space or Enter fails while click opening and Close work, help-toggle acceptance evidence can be missed.'),
'S-1':(method_counter,method_ref,'When a disallowed method is attempted, this protocol does not establish the required method boundary or retained blocked-request effects.'),
'S-2':(origin_counter,origin_ref,'When a followed link, redirect or request leaves the sole authorized origin, the protocol supplies no boundary check.'),
'F-201':(help_counter,help_ref,'When summary Space or Enter fails while click opening and Close work, help-toggle acceptance evidence can be missed.'),
'F-202':(back_counter,back_ref,'When pointer Back works but sequential keyboard Back fails, the required keyboard-back check can be missed.'),
'F-203':(method_counter+' '+origin_counter,method_ref+' '+origin_ref,'When the journey attempts a disallowed method or origin, the target can complete its UI assertions without the required boundary evidence.')}
findings=[]
for claim in packet['findings']:
    counter,refutation,impact=items[claim['id']]
    finding=dict(claim)
    finding.update(verdict='CONFIRMED',counterexample=counter,refutation_attempt=refutation,condition_and_consequence=impact)
    finding['evidence'] += ' Independently inspected raw sources; actual offline checks and controls are saved in verifier-checks.json and verifier-reproduce-output.txt; executable reproduction: verifier-reproduce.py. Confirmation is limited to documentary coverage.'
    findings.append(finding)
assert len(findings)==7 and len({f['id'] for f in findings})==7
assert all(f['severity']=='medium' and f['counterexample'] and f['refutation_attempt'] for f in findings)
(OUT/'verified.json').write_text(json.dumps({'findings':findings},indent=2)+'\n')
ids=[f['id'] for f in findings]
coverage={
'execution_coverage':'COMPLETE',
'phase':'fresh independent verifier only',
'input':'/workspace/output/evidence/claims.json',
'examined_ids':ids,'unexamined_ids':[],
'batches':[{'order':1,'ids':['S-1','S-2','F-203'],'priority':'authorization boundary consequences first'},{'order':2,'ids':['C-1','F-202','C-2','F-201'],'priority':'keyboard acceptance evidence'}],
'verdicts':{'CONFIRMED':7,'PLAUSIBLE':0,'REFUTED':0},
'verified_blocker_ids':[],
'duplicates_preserved':[['C-1','F-202'],['C-2','F-201'],['S-1','S-2','F-203']],
'checks':[{'command':'python3 -B /workspace/output/evidence/verifier-reproduce.py > /workspace/output/evidence/verifier-reproduce-output.txt','exit_code':0,'output_files':['/workspace/output/evidence/verifier-reproduce-output.txt','/workspace/output/evidence/verifier-checks.json'],'description':'Actual validator call, exact-source assertions, four offline defective UI fixtures, healthy UI control, pure in-memory request-policy countermodels and enforcement control.'}],
'snapshot_sha256':checks['target_sha256'],
'limits':['Synthetic fixtures demonstrate protocol coverage, not website behavior.','No network, browser or live-site verification; no website defect asserted.','No source/input/shared-data mutations; only evidence files written.','No finder reports or reasoning read; original redacted IDs/severity retained.','Only verifier roster can be attested here: requested 1, returned 1.','No release/acceptance decision is authorized or inferred.'],
'completed_at_utc':datetime.now(timezone.utc).isoformat()
}
(OUT/'verification-coverage.json').write_text(json.dumps(coverage,indent=2)+'\n')
report=['# Independent verifier report', '', 'Execution coverage: **COMPLETE** for all seven supplied claims. Verdicts: **7 CONFIRMED, 0 PLAUSIBLE, 0 REFUTED**. Every claim remains medium severity; none is a verified critical/high blocker. Duplicate claims remain separately preserved. Confirmation concerns gaps in a reconstructed documentary fixture, never current website behavior.', '', 'The verifier read only the mechanically redacted claims, the raw target, the surface contract, its checker, the observation policy, and the two permitted skill references. No finder reasoning, source snapshots, network or website observations were used. Requested/returned verifier roles: 1/1. Finder-role completeness is outside this verifier context.', '', '## Method and actual checks', '', 'Command: `python3 -B /workspace/output/evidence/verifier-reproduce.py > /workspace/output/evidence/verifier-reproduce-output.txt` (exit 0). Script and actual stdout are retained. Structured actual traces, source hashes, static assertions, contract-validator output, and controls are in `verifier-checks.json`.', '', 'Batch 1 examined S-1, S-2, F-203 first because their stated conditions concern authorization boundaries. Batch 2 examined C-1, F-202, C-2, F-201. The source-to-consumer chain was followed from declared transition/policy fields through the JSON-only validator to the six written observation steps. The validator emits `valid`, `schema`, `checks`, `limit`; it emits no browser observations, enforcement configuration or evidence of blocked-request effects. Its successful declaration check therefore cannot close these runtime-evidence gaps.', '', 'The offline UI state machines are deliberately synthetic implementations of the stated controls; their failures are stipulated input conditions. They demonstrate that written target assertions can all pass while an explicitly required transition fails. The offline request queue is pure data processing with an in-memory sink; its delivered/blocked labels describe the simulation only. A healthy UI control and explicit-policy request control test the strongest available counterarguments. These are coverage counterexamples, not reconstructions of the actual site.', '']
for f in findings:
    report += ['## '+f['id']+' — '+f['title'], '', '**'+f['severity']+' / '+f['verdict']+' / nonblocking under the critical-high blocker rule**', '', '**Evidence:** '+f['evidence'], '', '**Condition and consequence:** '+f['condition_and_consequence'], '', '**Concrete reproduction:** '+f['counterexample'], '', '**Evidence-backed refutation attempt:** '+f['refutation_attempt'], '', '**Disposition:** Retain the documentary coverage finding. No target edits were made; any fix must explicitly cover the applicable declared transition or policy and be reverified.', '']
report += ['## Coverage, snapshot and limits', '', 'Examined: '+', '.join(ids)+'. Unexamined: none. Totals: 7 confirmed / 0 plausible / 0 refuted. No independent website behavior was tested. No delivery decision follows from COMPLETE phase coverage or medium-only findings.', '', 'Target and criteria SHA-256:', '']
for path,digest in checks['target_sha256'].items(): report += ['- `'+path+'`: `'+digest+'`']
report += ['', 'Canonical coverage record: `verification-coverage.json`. Final strict envelope: `verified.json`. No corrections or input mutations were performed.']
(OUT/'verifier-report.md').write_text('\n'.join(report)+'\n')
print(json.dumps({'written':['verifier-report.md','verified.json','verification-coverage.json'],'examined_ids':ids,'unexamined_ids':[],'verdicts':coverage['verdicts'],'execution_coverage':'COMPLETE'},indent=2))
